// ---- Calculation, ported from the VBA modules -----------------------------

// VBA Round(x, 2): scale the double by 100, then round half to even only when
// the scaled double is exactly .5 (banker's rounding, no tolerance).
function vbaRound2(x) {
  const y = x * 100;
  const f = Math.floor(y);
  const d = y - f;
  let r;
  if (d === 0.5) r = f % 2 === 0 ? f : f + 1;
  else r = d > 0.5 ? f + 1 : f;
  return r / 100;
}

// FunctionTELOS.Telos
function telos(amount) {
  let t = 0, prev = 0;
  for (const b of BANDS) {
    if (amount > b.to) { t += (b.to - prev) * b.rate; prev = b.to; }
    else { t += (amount - prev) * b.rate; break; }
  }
  return t;
}

// Function_date_diff_to_months.date_diff_to_months
function monthsLate(d1, d2) {
  const mDiff = d2.m - d1.m;
  const yDiff = (d2.y - d1.y) * 12;
  const adj = (mDiff > 0 || yDiff > 0) && d2.d < d1.d ? -1 : 0;
  return mDiff + yDiff + adj;
}

function daysBetween(d1, d2) {
  return Math.round((Date.UTC(d2.y, d2.m - 1, d2.d) - Date.UTC(d1.y, d1.m - 1, d1.d)) / 86400000);
}

// FunctionCharges.Charges, written in the same arithmetic order as the VBA
function charges(t, months, days) {
  if (months === 0 && days <= 30) return 0;
  if (t <= 35) {
    if (months === 0) return t;
    if (months <= 6 && days <= 30) return 0;
    if (months < 6) return t;
    return t * 2;
  }
  if (months === 0) return 35 + (t - 35) * 0.1;
  if (months <= 6 && days <= 30) return 0;
  if (months < 6) return 35 + (t - 35) * 0.1;
  return 35 * 2 + (t - 35) * 0.1 * 2;
}

// ---- Article 20 of the Stamp Duty Law, read literally (cents as integers) --
// Rates: €0 up to €5.000; €1,50 per €1.000 or part from €5.001 to €170.000;
// €2,00 per €1.000 or part above €170.000; at most €20.000.
function telosLaw(amount) {
  if (amount <= 5000) return 0;
  const thousands = x => Math.ceil(x / 1000 - 1e-9);
  let cents = thousands(Math.min(amount, 170000) - 5000) * 150;
  if (amount > 170000) cents += thousands(amount - 170000) * 200;
  return Math.min(cents, 2000000) / 100;
}

// Stamping date falls within six calendar months of the first signature.
function withinSixMonths(d1, d2) {
  let y = d1.y, m = d1.m + 6;
  if (m > 12) { m -= 12; y += 1; }
  const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
  const limit = { y, m, d: Math.min(d1.d, last) };
  return dateKey(d2) <= dateKey(limit);
}

// Art. 20(a)–(c): nothing within 30 days; within six months (i) duty ≤ €2 → €2,
// (ii) ≤ €35 → equal to the duty, (iii) above → €35 + 10 cents per euro or part
// of the excess; after six months double those amounts.
function chargesLaw(t, days, inSixMonths) {
  if (t === 0 || days <= 30) return 0;
  const tc = Math.round(t * 100);
  let cents;
  if (tc <= 200) cents = 200;
  else if (tc <= 3500) cents = tc;
  else cents = 3500 + 10 * Math.ceil((tc - 3500) / 100);
  return (inSixMonths ? cents : cents * 2) / 100;
}

// Calculate_11 … Calculate_31, shared tail
function calculate(cat, v, mode = "tool") {
  let amount, theoreticalYrs = null;
  switch (cat) {
    case 11: amount = v.down + v.rent * v.periods; break;
    case 12: theoreticalYrs = YEARS.akiniti12; amount = v.down + v.rent * theoreticalYrs; break;
    case 21: amount = v.salary * v.periods; break;
    case 22: theoreticalYrs = YEARS.employment22; amount = v.salary * theoreticalYrs; break;
    case 23: theoreticalYrs = YEARS.employment23; amount = v.salary * theoreticalYrs; break;
    case 31: amount = v.amount; break;
  }
  const numMonthsLate = monthsLate(v.dateContract, v.dateStamp);
  const numDaysLate = daysBetween(v.dateContract, v.dateStamp);
  let totalTelos, totalCharges;
  if (mode === "law") {
    totalTelos = telosLaw(amount);
    totalCharges = chargesLaw(totalTelos, numDaysLate, withinSixMonths(v.dateContract, v.dateStamp));
  } else {
    totalTelos = vbaRound2(telos(amount));
    totalCharges = vbaRound2(charges(totalTelos, numMonthsLate, numDaysLate));
  }
  const stamps = totalTelos + totalCharges;
  // Match the workbook in tool mode; the law-mode copy fee uses the duty on
  // the original before late charges.
  const copyBasis = mode === "law" ? totalTelos : stamps;
  let copyTotalCharge;
  if (copyBasis === 0) copyTotalCharge = 0;
  else if (copyBasis > 2) copyTotalCharge = v.copies * COPY_CHARGE;
  else copyTotalCharge = v.copies * copyBasis;
  const total = stamps + copyTotalCharge;
  let printReport;
  if (totalCharges > 0 || stamps > 100) printReport = 1;
  else if (totalCharges === 0 && total > 0) printReport = 2;
  else printReport = 0;
  return { cat, mode, ...v, amount, theoreticalYrs, totalTelos, numMonthsLate, numDaysLate,
    totalCharges, stamps, copyTotalCharge, total, printReport };
}

// FUNCTIONS.LastDigit: check letter of a Cyprus T.I.C.
const ODD_MAP = [1, 0, 5, 7, 9, 13, 15, 17, 19, 21];
function ticLetter(eight) {
  if (!/^\d{8}$/.test(eight)) return "Error";
  let sum = 0;
  for (let i = 0; i < 8; i++) {
    const d = +eight[i];
    sum += i % 2 === 0 ? ODD_MAP[d] : d;
  }
  return String.fromCharCode(65 + (sum % 26));
}
function ticValid(tic) {
  return tic.length === 9 && /^\d{8}[A-Za-z]$/.test(tic) && ticLetter(tic.slice(0, 8)) === tic[8].toUpperCase();
}

// ---- Formatting -----------------------------------------------------------
const nf2 = new Intl.NumberFormat("el-GR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const nf0 = new Intl.NumberFormat("el-GR", { maximumFractionDigits: 0 });
const money = x => nf2.format(x);
const pad = n => String(n).padStart(2, "0");
const fmtDate = d => `${pad(d.d)}/${pad(d.m)}/${d.y}`;
const esc = s => String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

// ---- Input parsing (the Excel tool wanted a comma; accept comma or dot) ---
function parseAmount(raw) {
  let s = String(raw).trim().replace(/\s|€/g, "");
  if (s === "") return NaN;
  if (s.includes(",") && s.includes(".")) return NaN;
  s = s.replace(",", ".");
  if (!/^-?\d+(\.\d+)?$/.test(s)) return NaN;
  return parseFloat(s);
}
function parseInteger(raw) {
  const s = String(raw).trim();
  return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
}
function parseDate(raw) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(raw || "");
  return m ? { y: +m[1], m: +m[2], d: +m[3] } : null;
}
const dateKey = d => d.y * 10000 + d.m * 100 + d.d;

