function validateInput(cat) {
  const err = [];
  const v = {};
  const priorDuty = document.querySelector('input[name="prior-duty"]:checked')?.value;
  if (!priorDuty) return { err: ["ΕΠΙΛΕΞΤΕ ΑΝ ΕΧΕΙ ΗΔΗ ΚΑΤΑΒΛΗΘΕΙ ΤΕΛΟΣ ΧΑΡΤΟΣΗΜΟΥ (SELECT WHETHER ANY STAMP DUTY HAS ALREADY BEEN PAID)"], v };
  if (priorDuty === "yes") return { err: ["ΤΟ ΕΡΓΑΛΕΙΟ ΔΕΝ ΥΠΟΛΟΓΙΖΕΙ ΤΟ ΥΠΟΛΟΙΠΟ ΤΕΛΟΣ ΓΙΑ ΜΕΡΙΚΩΣ ΧΑΡΤΟΣΗΜΑΣΜΕΝΟ ΕΓΓΡΑΦΟ. ΖΗΤΗΣΤΕ ΕΚΤΙΜΗΣΗ ΑΠΟ ΤΟ ΤΜΗΜΑ ΦΟΡΟΛΟΓΙΑΣ (THIS TOOL CANNOT CALCULATE THE BALANCE FOR A PARTIALLY STAMPED DOCUMENT. ASK THE TAX DEPARTMENT TO ASSESS IT)"], v };
  const amountField = (id, key, bad, neg) => {
    const x = parseAmount($(id).value);
    if (isNaN(x)) err.push(bad); else if (x < 0) err.push(neg); else v[key] = x;
  };
  if (cat === 11 || cat === 12) amountField("f-down", "down",
    "ΛΑΘΟΣ ΣΤΟ ΠΟΣΟ ΠΡΟΚΑΤΑΒΟΛΗΣ (ERROR IN DOWN PAYMENT)",
    "ΤΟ ΠΟΣΟ ΠΡΟΚΑΤΑΒΟΛΗΣ ΔΕΝ ΜΠΟΡΕΙ ΝΑ ΕΙΝΑΙ ΑΡΝΗΤΙΚΟ (THE DOWN PAYMENT CANNOT BE NEGATIVE)");
  if (cat === 11) amountField("f-rent11", "rent",
    "ΛΑΘΟΣ ΣΤΟ ΠΟΣΟ ΜΙΣΘΩΣΗΣ ΑΝΑ ΠΕΡΙΟΔΟ (ERROR IN RENTAL AMOUNT PER PERIOD)",
    "ΤΟ ΠΟΣΟ ΜΙΣΘΩΣΗΣ ΑΝΑ ΠΕΡΙΟΔΟ ΔΕΝ ΜΠΟΡΕΙ ΝΑ ΕΙΝΑΙ ΑΡΝΗΤΙΚΟ (THE RENTAL AMOUNT PER PERIOD CANNOT BE NEGATIVE)");
  if (cat === 12) amountField("f-rent12", "rent",
    "ΛΑΘΟΣ ΣΤΟ ΕΤΗΣΙΟ ΠΟΣΟ ΜΙΣΘΩΣΗΣ (ERROR IN RENTAL AMOUNT PER ANNUM)",
    "ΤΟ ΕΤΗΣΙΟ ΠΟΣΟ ΜΙΣΘΩΣΗΣ ΔΕΝ ΜΠΟΡΕΙ ΝΑ ΕΙΝΑΙ ΑΡΝΗΤΙΚΟ (THE RENTAL AMOUNT PER ANNUM CANNOT BE NEGATIVE)");
  const salaryId = { 21: "f-sal21", 22: "f-sal22", 23: "f-sal23" }[cat];
  if (salaryId) amountField(salaryId, "salary",
    "ΛΑΘΟΣ ΣΤΟ ΜΙΣΘΟ ΑΝΑ ΠΕΡΙΟΔΟ (ERROR IN SALARY AMOUNT PER PERIOD)",
    "ΤΟ ΜΙΣΘΟΣ ΑΝΑ ΠΕΡΙΟΔΟ ΔΕΝ ΜΠΟΡΕΙ ΝΑ ΕΙΝΑΙ ΑΡΝΗΤΙΚΟ (THE SALARY PER PERIOD CANNOT BE NEGATIVE)");
  if (cat === 31) amountField("f-amount", "amount",
    "ΛΑΘΟΣ ΣΤΗΝ ΑΞΙΑ ΣΥΜΒΟΛΑΙΟΥ (ERROR IN THE VALUE OF CONTRACT)",
    "H ΑΞΙΑ ΣΥΜΒΟΛΑΙΟΥ ΔΕΝ ΜΠΟΡΕΙ ΝΑ ΕΙΝΑΙ ΑΡΝΗΤΙΚΗ (THE VALUE OF CONTRACT CANNOT BE NEGATIVE)");
  if (cat === 11 || cat === 21) {
    const p = parseInteger($("f-periods").value);
    if (isNaN(p)) err.push("ΛΑΘΟΣ ΣΤΟΝ ΑΡΙΘΜΟ ΠΕΡΙΟΔΩΝ (ERROR IN NUMBER OF PERIODS)");
    else if (p < 0) err.push("O ΑΡΙΘΜΟΣ ΠΕΡΙΟΔΩΝ ΔΕΝ ΜΠΟΡΕΙ ΝΑ ΕΙΝΑΙ ΑΡΝΗΤΙΚΟ (THE NUMBER OF PERIODS CANNOT BE NEGATIVE)");
    else if (p > 32767) err.push("Ο ΑΡΙΘΜΟΣ ΠΕΡΙΟΔΩΝ EIΝΑΙ ΜΕΓΑΛΟΣ (THE NUMBER OF PERIODS IS VERY LARGE)");
    else v.periods = p;
  }
  const dc = parseDate($("f-dcontract").value), ds = parseDate($("f-dstamp").value);
  if (!dc) err.push("ΛΑΘΟΣ ΣΤΗΝ ΗΜΕΡ. ΣΥΜΒΟΛΑΙΟΥ (ERROR IN THE DATE OF CONTRACT)");
  else if (dateKey(dc) > 20251231) err.push("Η ΣΥΜΒΑΣΗ ΔΕΝ ΥΠΟΚΕΙΤΑΙ ΣΕ ΤΕΛΟΣ ΧΑΡΤΟΣΗΜΟΥ ΜΕ ΒΑΣΗ ΤΟΝ Ν. 239(Ι)/2025 (THE AGREEMENT IS NOT SUBJECT TO STAMP DUTY PURSUANT TO LAW 239(I)/2025)");
  if (!ds) err.push("ΛΑΘΟΣ ΣΤΗΝ ΗΜΕΡ. ΧΑΡΤΟΣΗΜΑΝΣΗΣ (ERROR IN THE DATE OF STAMPING)");
  if (dc && ds && dateKey(ds) < dateKey(dc))
    err.push("Η ΗΜΕΡ. ΧΑΡΤΟΣΗΜΑΝΣΗΣ ΔΕΝ ΜΠΟΡΕΙ ΝΑ ΕΙΝΑΙ ΜΙΚΡΟΤΕΡΗ ΤΗΣ ΗΜΕΡ. ΣΥΜΒΟΛΑΙΟΥ (THE DATE OF STAMPING CANNOT BE BEFORE THE DATE OF CONTRACT)");
  v.dateContract = dc; v.dateStamp = ds;
  const c = parseInteger($("f-copies").value);
  if (isNaN(c)) err.push("ΛΑΘΟΣ ΣΤΟΝ ΑΡΙΘΜΟ ΑΝΤΙΓΡΑΦΩΝ (ERROR IN COPIES)");
  else if (c < 0) err.push("Ο ΑΡΙΘΜΟΣ ΑΝΤΙΓΡΑΦΩΝ ΔΕΝ ΜΠΟΡΕΙ ΝΑ ΕΙΝΑΙ ΑΡΝΗΤΙΚΟΣ (THE NUMBER OF COPIES CANNOT BE NEGATIVE)");
  else if (c > 32767) err.push("Ο ΑΡΙΘΜΟΣ ΑΝΤΙΓΡΑΦΩΝ ΕΙΝΑΙ ΠΟΛΥ ΜΕΓΑΛΟΣ (THE NUMBER OF COPIES IS VERY LARGE)");
  else v.copies = c;
  return { err, v };
}

// Rows of the results screen and of the printed form (Create_Sheet order).
function inputRows(r) {
  switch (r.cat) {
    case 11: return [
      ["Προκαταβολή (Down payment):", money(r.down)],
      ["Ποσό μίσθωσης ανά περίοδο / μήνα (Rental amount per period / month):", money(r.rent)],
      ["Αριθμός περιόδων / μηνών (Number of periods / months):", money(r.periods)]];
    case 12: return [
      ["Προκαταβολή (Down payment):", money(r.down)],
      ["Ποσό μίσθωσης ανά έτος (Rental amount per annum):", money(r.rent)],
      ["Αριθμός θεωρητικών ετών (Number of theoretical years):", money(r.theoreticalYrs)]];
    case 21: return [
      ["Αντιπαροχή ανά περίοδο/μήνα (Compensation per period/month:", money(r.salary)],
      ["Αριθμός περιόδων /μηνών (Number of periods / months):", money(r.periods)]];
    case 22: case 23: return [
      [r.cat === 22 ? "Ετήσια πρόσοδος (Annuity):" : "Ετήσια Αντιπαροχή (Annual Compensation):", money(r.salary)],
      ["Θεωρητικά έτη (Theoretical years):", money(r.theoreticalYrs)]];
    default: return [];
  }
}
function commonRows(r) {
  return [
    ["Συνολική αξία (Total amount):", money(r.amount)],
    ["Σύνολο χαρτοσήμων πριν τις επιβαρύνσεις (Total stamp duty tax before charges):", money(r.totalTelos)],
    ["Ημερομηνία πρώτης υπογραφής (date of first signature):", fmtDate(r.dateContract)],
    ["Ημερομηνία χαρτοσήμανσης (date of stamping):", fmtDate(r.dateStamp)],
    ["Μήνες καθυστέρησης χαρτοσήμανσης (number of months late in stamping):", nf0.format(r.numMonthsLate)],
    ["Μέρες καθυστέρησης χαρτοσήμανσης (number of days late in stamping):", nf0.format(r.numDaysLate)],
    ["Σύνολο επιβαρύνσεων (Total charges):", money(r.totalCharges)],
    ["Τελικό τέλος χαρτοσήμων (Final stamp duty tax):", money(r.stamps)],
    ["Αριθμός αντιγράφων  (Number of copies):", nf0.format(r.copies)],
    ["Χρέωση για χαρτοσήμανση αντιγράφων (charge for copies)", money(r.copyTotalCharge)],
    ["Συνολικό Ποσό (Total Amount)", money(r.total)],
  ];
}
const rowsHtml = rows => rows.map((row, i) =>
  `<tr${i === rows.length - 1 ? ' class="total"' : ""}><td>${esc(row[0])}</td><td class="v">${esc(row[1])}</td></tr>`).join("");

$("btn-calc").addEventListener("click", () => {
  const { err, v } = validateInput(currentCat);
  const box = $("input-errors");
  if (err.length) { box.textContent = err.join("\n"); box.classList.remove("hidden"); return; }
  box.classList.add("hidden");
  result = { ...calculate(currentCat, v, currentMode()), title: currentOpt.title };
  $("results-title").textContent = result.title.join(" ");
  $("results-mode").textContent = MODE_LABEL[result.mode];
  $("results-table").innerHTML = rowsHtml([...inputRows(result), ...commonRows(result)]);
  $("tic-label").textContent = result.printReport === 1
    ? "ΑΡΙΘΜΟΣ ΦΟΡΟΛΟΓΙΚΟΥ ΜΗΤΡΩΟΥ (Α.Φ.Μ)-TAX IDENTIFICATION CODE (TIC)*"
    : "ΑΡΙΘΜΟΣ ΦΟΡΟΛΟΓΙΚΟΥ ΜΗΤΡΩΟΥ (Α.Φ.Μ)/ΤΑΥΤΟΤΗΤΑ-TAX IDENTIFICATION CODE (TIC)/ID NUMBER*";
  show("results");
});

$("btn-report").addEventListener("click", () => {
  const tic = $("f-tic").value.trim(), name = $("f-name").value.trim();
  const err = [];
  if (result.printReport === 1 && !ticValid(tic))
    err.push("ΛΑΘΟΣ ΣΤΟΝ ΑΡΙΘΜΟ ΦΟΡΟΛΟΓΙΚΟΥ ΜΗΤΡΩΟΥ (Α.Φ.Μ)-ΠΡΕΠΕΙ ΝΑ ΑΠΟΤΕΛΕΙΤΑΙ ΑΠΟ 9 ΨΗΦΙΑ. ΤΑ ΠΡΩΤΑ 8 ΨΗΦΙΑ ΝΑ ΕΙΝΑΙ ΑΡΙΘΜΟΙ ΚΑΙ ΤΟ ΤΕΛΕΥΤΑΙΟ ΝΑ ΕΙΝΑΙ ΛΑΤΙΝΙΚΟ ΓΡΑΜΜΑ. (ERROR IN THE TAX IDENTIFICATION CODE (TIC). IT SHOULD CONSIST OF 9 CHARACTERS. THE FIRST 8 CHARACTERS SHOULD BE NUMBERS AND THE LAST SHOULD BE A LATIN CHARACTER, MATCHING THE CHECK LETTER.)");
  if (name.length < 3) err.push("ΛΑΘΟΣ ΣΤΟ ΟΝΟΜΑ ΦΟΡΟΛΟΓΟΥΜΕΝΟΥ-ERROR IN THE TAXPAYER NAME");
  const parties = [1, 2, 3].map(n => ({ name: $("f-p" + n).value.trim(), number: $("f-p" + n + "n").value.trim() }));
  if (parties[0].name.length < 3) err.push("ΛΑΘΟΣ ΣΤΟ ΟΝΟΜΑ ΤΟΥ ΣΥΜΒΑΛΛΟΜΕΝΟΥ 1-ERROR IN THE NAME OF THE CONTRACTING PARTY 1");
  if (parties[1].name.length < 3) err.push("ΛΑΘΟΣ ΣΤΟ ΟΝΟΜΑ ΤΟΥ ΣΥΜΒΑΛΛΟΜΕΝΟΥ 2-ERROR IN THE NAME OF THE CONTRACTING PARTY 2");
  const box = $("names-errors");
  if (err.length) { box.textContent = err.join("\n"); box.classList.remove("hidden"); return; }
  box.classList.add("hidden");
  renderReport(result, tic, name, parties);
  show("report");
});

function renderReport(r, tic, name, parties) {
  // Format_Report: party lines, number in brackets when given; party 3 only if named.
  const partyLines = parties.map((p, i) => (i < 2 || p.name)
    ? `<div class="who">ΣΥΜΒΑΛΛΟΜΕΝΟΣ ${i + 1} (CONTRACTING PARTY ${i + 1}): ${esc(p.name)}${p.number ? " (" + esc(p.number) + ")" : ""}</div>`
    : "").join("");
  const [gr, en] = r.title;
  const now = new Date();
  $("report").innerHTML = `
    <div class="ph">STAMP DUTIES V4</div>
    <img class="logo" src="${LOGO}" alt="ΤΜΗΜΑ ΦΟΡΟΛΟΓΙΑΣ / TAX DEPARTMENT">
    <div class="who">ΑΡΙΘΜΟΣ ΦΟΡΟΛΟΓΙΚΟΥ ΜΗΤΡΩΟΥ (Α.Φ.Μ)/ΤΑΥΤΟΤΗΤΑ-TAX IDENTIFICATION CODE (TIC)/ID NUMBER: ${esc(tic)}</div>
    <div class="who">ΟΝΟΜΑ ΦΟΡΟΛΟΓΟΥΜΕΝΟΥ-TAXPAYER'S NAME: ${esc(name)}</div>
    ${partyLines}
    <div class="h">ΥΠΟΛΟΓΙΣΜΟΣ ΤΕΛΟΥΣ ΧΑΡΤΟΣΗΜΩΝ (COMPUTATION OF STAMP DUTY TAX)</div>
    <table>
      <tr class="cat"><td colspan="2">${esc(gr)}</td></tr>
      <tr class="cat"><td colspan="2">${esc(en)}</td></tr>
      <tr><td></td><td class="v" style="text-align:center">€</td></tr>
      ${rowsHtml([...inputRows(r), ...commonRows(r)])}
    </table>
    <div class="pf">${esc(MODE_LABEL[r.mode])}<br>${fmtDate({ y: now.getFullYear(), m: now.getMonth() + 1, d: now.getDate() })} ${pad(now.getHours())}:${pad(now.getMinutes())}</div>
    <div class="scope">Ο υπολογισμός προϋποθέτει ότι δεν έχει καταβληθεί τέλος χαρτοσήμου για το πρωτότυπο. Από 01/04/2026 η διαδικασία για έγγραφα που υπόκεινται σε τέλος αρχίζει μέσω Tax For All· το Τμήμα Φορολογίας επιβεβαιώνει το οφειλόμενο ποσό.<br>The calculation assumes no duty has been paid on the original. From 01/04/2026, the procedure for taxable originals begins through Tax For All; the Tax Department confirms the amount due.</div>`;
}

